protocol SupportOutput: Sendable {
    /// Configuration that determines the generated support declaration.
    var configuration: Configuration { get }

    /// Generated Swift declarations, using four spaces per indentation level.
    var source: String { get }

    /// Top-level Swift types generated by this output.
    var topLevelTypeNames: [SwiftTypeIdentifier] { get }
}

extension SupportOutput {
    var accessLevel: String {
        configuration.output.support.accessLevel == .public ? "public " : ""
    }

    var indentedSource: String {
        let indentation = configuration.output.indentation.string
        return source.split(separator: "\n", omittingEmptySubsequences: false)
            .map { line in
                let leadingSpaces = line.prefix(while: { $0 == " " }).count
                return String(repeating: indentation, count: leadingSpaces / 4)
                    + String(line.dropFirst(leadingSpaces - leadingSpaces % 4))
            }
            .joined(separator: "\n")
    }
}
